            || ($record['electors'] ?? null) !== $source['detail']['electors']
            || ($record['votes_polled'] ?? null) !== $source['detail']['votes_polled']
            || ($record['valid_candidate_votes'] ?? null) !== $source['detail']['valid_candidate_votes']) {
